// === Teil 1 (Partner Voice Exam derived automatically from Teil 2 & Teil 3) ===
(function buildTeil1FromT2T3() {
  const stopWords = new Set(["ich","du","er","sie","es","wir","ihr","und","oder","aber","denn","weil","dass","wenn","als","wie","wo","wer","was","wann","warum","mit","für","von","zu","zum","zur","im","in","an","am","auf","aus","bei","nach","vor","über","unter","um","durch","ohne","gegen","der","die","das","den","dem","des","ein","eine","einen","einem","einer","mein","meine","meinen","meiner","dein","sehr","viel","viele","mehr","auch","nur","noch","schon","immer","nie","oft","nicht","kein","keine","keinen","kann","kannst","können","muss","müssen","möchte","möchten","will","wollen","soll","sollen","habe","haben","hat","bin","bist","ist","sind","war","wäre","würde","wird","werden","man","sich","mir","mich","dir","dich","uns","euch","ihnen","dieser","diese","dieses","hier","dort","dann","so","da","mal","ja","nein","gut","besser","beste","gern","gerne","lieber","etwas","alles","nichts","person","personen","zeit","jahre","jahr","tag","tage"]);
  const extractKw = (txt) => {
    const words = (txt || "").replace(/[.,!?;:„“"()•–—]/g, " ").split(/\s+/).filter(w => w.length >= 4);
    const seen = new Set();
    const res = [];
    for (const w of words) {
      const low = w.toLowerCase();
      if (!stopWords.has(low) && !seen.has(low)) {
        seen.add(low);
        res.push(w);
        if (res.length >= 10) break;
      }
    }
    return res;
  };

  const t1FromT2 = window.SAHLA_DATA.b1.sprechen.teil2.map((lesson, idx) => ({
    id: `b1-sp1-t2-${lesson.order}`,
    order: idx + 1,
    sourceType: "teil2",
    sourceId: lesson.id,
    title: lesson.title,
    titleAr: lesson.titleAr,
    level: "B1",
    sub: "Teil 1",
    type: "sprechen_partner",
    aufgabe: `Partnergespräch zum Thema „${lesson.title}“: Tauschen Sie sich auf Deutsch aus, berichten Sie über Ihre eigenen Erfahrungen und reagieren Sie auf die Meinung Ihres Partners.`,
    aufgabeAr: `حوار صوتي ثنائي حول موضوع "${lesson.titleAr}": تحاورا بالألمانية، تكلما على تجاربكم الشخصية وتفاعلا مع رأي الصديق.`,
    roleA: {
      label: "Person A",
      focus: lesson.personA.de,
      focusAr: lesson.personA.ar,
      tasks: [
        `Begrüßen Sie Ihren Partner und stellen Sie das Thema „${lesson.title}“ kurz vor.`,
        "Erklären Sie Ihre persönliche Erfahrung oder Meinung (inspiriert von Meinung A).",
        `Stellen Sie Ihrem Partner 2 Fragen zum Thema „${lesson.title}“ und reagieren Sie auf seine Antwort.`
      ]
    },
    roleB: {
      label: "Person B",
      focus: lesson.personB.de,
      focusAr: lesson.personB.ar,
      tasks: [
        "Begrüßen Sie Ihren Partner und beantworten Sie seine Fragen.",
        "Sagen Sie Ihre Meinung oder Gegenerfahrung (inspiriert von Meinung B).",
        "Stellen Sie eine Rückfrage und fassen Sie am Ende Ihre gemeinsame Meinung zusammen."
      ]
    },
    keywords: extractKw(lesson.title + " " + lesson.personA.de + " " + lesson.personB.de),
    redemittel: ["Meiner Meinung nach ...", "Ich finde, dass ...", "Wie siehst du das?", "Da stimme ich dir zu.", "Ich sehe das anders, weil ..."]
  }));

  const t1FromT3 = window.SAHLA_DATA.b1.sprechen.teil3.map((lesson, idx) => ({
    id: `b1-sp1-t3-${lesson.order}`,
    order: t1FromT2.length + idx + 1,
    sourceType: "teil3",
    sourceId: lesson.id,
    title: `Planung: ${lesson.title}`,
    titleAr: `تخطيط مشترك: ${lesson.titleAr}`,
    level: "B1",
    sub: "Teil 1",
    type: "sprechen_partner",
    aufgabe: lesson.aufgabe,
    aufgabeAr: lesson.aufgabeAr,
    punkte: lesson.punkte,
    punkteAr: lesson.punkteAr,
    roleA: {
      label: "Person A",
      focus: lesson.punkte.slice(0, Math.ceil(lesson.punkte.length / 2)).join(" • "),
      focusAr: (lesson.punkteAr || []).slice(0, Math.ceil(lesson.punkte.length / 2)).join(" • "),
      tasks: [
        `Beginnen Sie das Planungsgespräch zu „${lesson.title}“.`,
        ...lesson.punkte.slice(0, Math.ceil(lesson.punkte.length / 2)).map(p => `Machen Sie einen Vorschlag zu: ${p}`),
        "Fragen Sie Ihren Partner nach seiner Meinung."
      ]
    },
    roleB: {
      label: "Person B",
      focus: lesson.punkte.slice(Math.ceil(lesson.punkte.length / 2)).join(" • ") || lesson.punkte[0],
      focusAr: (lesson.punkteAr || []).slice(Math.ceil(lesson.punkte.length / 2)).join(" • ") || (lesson.punkteAr || [])[0],
      tasks: [
        "Reagieren Sie auf den Vorschlag Ihres Partners (zustimmen oder Alternative nennen).",
        ...lesson.punkte.slice(Math.ceil(lesson.punkte.length / 2)).map(p => `Besprechen Sie den Punkt: ${p}`),
        "Einigen Sie sich gemeinsam auf einen klaren Plan."
      ]
    },
    keywords: extractKw(lesson.title + " " + lesson.punkte.join(" ") + " " + lesson.aufgabe),
    redemittel: ["Wir könnten ...", "Wie wäre es, wenn wir ...?", "Wann hast du Zeit?", "Das ist eine gute Idee!", "Abgemacht, so machen wir das."]
  }));

  window.SAHLA_DATA.b1.sprechen.teil1 = [...t1FromT2, ...t1FromT3];
})();
